// -------- selection --------
// Priority order (never a blind cycle, never pure randomness):
//   1. topic suitability      — keyword `signals` match, scored highest
//   2. subject suitability    — light per-subject affinity bonus
//   3. exam suitability       — folded into subject affinity today (no
//                                exam-only signal has a real basis yet;
//                                EXAM_PROFILES-level nuance already lives in
//                                the Master Prompt's TEACHING LEVEL/exam text)
//   4. teaching value         — encoded in `signals`/affinities themselves,
//                                which model actual topic/subject fit, not
//                                arbitrary preference
//   5. recent content-memory  — repetition penalty, below
//   6. avoid unnecessary reps — the penalty only demotes, never excludes, so
//                                a genuinely best-fit flavour used recently
//                                can still win (see TIE_EPSILON note)
//   7. randomness             — ONLY as a last-resort tie-break (hash of
//                                topic/exam/subject, not Math.random()) when
//                                nothing above distinguishes two flavours

const RECENT_WINDOW = 5;   // how many recent same-exam/subject records count against repetition
const TIE_EPSILON = 0.5;   // scores within this range of the top score are treated as tied —
                            // must stay below the smallest real signal increment (1, a subject-
                            // affinity bonus) so an actual better-fitting flavour always wins;
                            // it only catches genuine exact ties (e.g. the concept-first anchor).

function hashString(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function scoreFlavour(flavour, topicLower, subjectLower, recentIds) {
  let score = 0;
  for (const kw of flavour.signals) if (topicLower.includes(kw)) score += 3;
  // light subject-level defaults, additive on top of keyword matching above —
  // these are hints, not hard rules, so a strong topic-keyword match on a
  // different flavour can still outscore them.
  if (subjectLower.includes('math') && (flavour.id === 'worked-example' || flavour.id === 'problem-first')) score += 2;
  if ((subjectLower.includes('cdp') || subjectLower.includes('pedagog')) && (flavour.id === 'classroom-situation' || flavour.id === 'misconception-first' || flavour.id === 'case-to-concept')) score += 2;
  if (subjectLower.includes('history') && (flavour.id === 'chronology-cause-effect' || flavour.id === 'evidence-to-conclusion' || flavour.id === 'case-to-concept')) score += 2;
  if ((subjectLower.includes('science') || subjectLower.includes('evs') || subjectLower.includes('geography')) && (flavour.id === 'classification' || flavour.id === 'process-first' || flavour.id === 'evidence-to-conclusion')) score += 2;
  if ((subjectLower.includes('hindi') || subjectLower.includes('english') || subjectLower.includes('language')) && (flavour.id === 'classification' || flavour.id === 'compare-and-contrast' || flavour.id === 'rule-exception')) score += 1;
  // Neutral tie-break anchor: when a topic/subject gives no real signal at
  // all (every flavour scores 0), the hash-based tie-break below would
  // otherwise land on an arbitrary-looking flavour (e.g. chronology-cause-
  // effect for a grammar topic) — this tiny nudge makes the safest generic
  // choice win those true no-signal ties without ever outweighing a real
  // keyword/subject match (3 and 2 points respectively).
  if (flavour.id === 'concept-first') score += 0.1;
  const idx = recentIds.indexOf(flavour.id);
  if (idx !== -1) score -= (recentIds.length - idx) * 1.5; // most-recent use penalized hardest
  return score;
}

/**
 * Picks a flavour for one topic. Never a blind cycle and never pure
 * randomness: every flavour is scored on topic-keyword and subject fit,
 * then a repetition penalty is subtracted for flavours used recently on the
 * same exam+subject (heavier penalty the more recent the use) — but the
 * penalty only demotes, so the strongest teaching fit still wins if nothing
 * comparable exists (repeating a flavour is fine when it's genuinely the
 * best fit; novelty for its own sake is never the goal). Ties among
 * near-equal top scores are broken with a hash of the topic/exam/subject
 * (not time or Math.random()), so the same inputs always resolve the same
 * way and a rerun is reproducible.
 *
 * @param {{topic:string, subject?:string, exam?:string}} ctx
 * @param {Array<{flavour?:string, exam?:string, subject?:string}>} recentMemory
 *   content-memory records, most-recent-first. Filtered internally to
 *   records matching ctx's exam and/or subject (loose: a record missing
 *   either field is treated as a match on that field so older records
 *   without a subject still count).
 */
function selectFlavour(ctx, recentMemory = []) {
  const topic = String(ctx.topic || '');
  const subject = String(ctx.subject || '');
  const exam = String(ctx.exam || '');
  const topicLower = topic.toLowerCase();
  const subjectLower = subject.toLowerCase();

  const recentIds = recentMemory
    .filter(r => r && r.flavour && (!exam || !r.exam || r.exam === exam) && (!subject || !r.subject || r.subject === subject))
    .slice(0, RECENT_WINDOW)
    .map(r => r.flavour);

  const scored = FLAVOUR_ENGINE.map(f => ({ flavour: f, score: scoreFlavour(f, topicLower, subjectLower, recentIds) }));
  scored.sort((a, b) => b.score - a.score);

  const top = scored[0].score;
  const tied = scored.filter(s => s.score >= top - TIE_EPSILON);
  const pick = tied[hashString(topic + '|' + exam + '|' + subject) % tied.length].flavour;

  return {
    selected: pick,
    candidates: scored.slice(0, 3).map(s => ({ id: s.flavour.id, score: s.score })),
    recentlyUsed: recentIds,
  };
}

/**
 * Renders the compact, model-facing block the Master Prompt's
 * {{FLAVOUR_ENGINE_BLOCK}} placeholder gets replaced with: the full menu
 * (so the model can override the suggestion when the topic genuinely calls
 * for something else — this is a recommendation, never a forced pick) plus
 * the engine's own suggestion and why. Never reveals internal scores/the
 * editorial plan itself — the model records its own actual choice in
 * Publisher Notes / the Content Memory block's "flavour" field.
 */
function buildFlavourPromptBlock(ctx, recentMemory = []) {
  const result = selectFlavour(ctx, recentMemory);
  // Compact format (id: flow — best for X) rather than the earlier
  // goal+flow+best_for-with-labels version: flow alone already conveys the
  // teaching sequence, and best_for stays as a short qualifier rather than
  // a third labeled clause — same 15 options, same information a human
  // would need to judge fit, considerably fewer characters per line since
  // this menu is printed in full on every single run regardless of topic.
  const menu = FLAVOUR_ENGINE.map(f =>
    `- **${f.id}**: ${f.flow} (${f.best_for[0]})`
  ).join('\n');
  const recentNote = result.recentlyUsed.length
    ? ` (recently used: ${result.recentlyUsed.join(', ')} — prefer a different one if comparable)`
    : '';
  return `${menu}\n\nSuggested: **${result.selected.id}**${recentNote}. Starting point, not a mandate — follow it unless the topic genuinely teaches better another way; never switch merely to avoid repetition. State your actual choice and why in Publisher Notes / the Content Memory block's "flavour" field.`;
}

